function fillSearch(){const q=$('searchPanelInput').value.trim().toLocaleLowerCase();
 $('searchResultsTitle').textContent=st(q?'results':'recommended');
 if(!q){$('searchPanelResults').innerHTML=`<div class="search-category-grid">${['Shorts','Leggings','Sets','Sports Bras'].map(c=>{const preferred={Shorts:['WH-W-SH-001','Copper'],Leggings:['WH-W-PT-001','Electric Blue'],Sets:['WH-W-UP-014','Ivy'],'Sports Bras':['WH-W-UP-004','Rose']};const [id,colour]=preferred[c];const p=products.find(p=>p.id===id&&p.image)||products.find(p=>!p.legacy&&p.category===c&&p.image);const photo=p?.referenceColors?.find(v=>v.name===colour)?.images[0]||p?.image;return p?`<a class="search-category" href="${href('women.html',{category:c})}"><img src="${referenceAsset(photo)}" alt="${h(t(c))}"><span>${h(t(c))}</span></a>`:''}).join('')}</div>`;return;}
 const matches=products.filter(p=>!p.legacy).filter(p=>[name(p),p.name,t(p.category),p.category,p.id].some(v=>String(v).toLocaleLowerCase().includes(q)));
 $('searchPanelResults').innerHTML=`<p class="search-count" role="status">${matches.length} ${h(st('results').toLocaleLowerCase())}</p>${matches.length?`<div class="search-products">${matches.slice(0,8).map(p=>`<a href="${href('product/'+p.type+'.html',{ref:p.id})}">${p.image?`<img src="${image(p)}" alt="${h(name(p))}">`:`<div class="search-no-photo">${h(t('photoPending'))}</div>`}<span>${h(name(p))}</span></a>`).join('')}</div><a class="search-all" href="${href('catalogue/index.html',{search:$('searchPanelInput').value.trim()})}">${h(st('all'))} (${matches.length})</a>`:`<p role="status">${h(st('empty'))}</p>`}`;
}

