function productSwatches(p,c,scope){let colors=p.referenceColors.slice(0,4);if(!colors.some(v=>v.name===c.name))colors=[...colors.slice(0,3),c];return `<div class="product-swatches" role="group" aria-label="${h(t('clColor'))}">${colors.map(v=>`<button class="product-swatch" ${scope==='home'?`data-home-swatch="${p.id}"`:`data-cl-color="${p.id}"`} data-color-name="${h(v.name)}" data-swatch-label="${h(v.name)}" aria-label="${h(v.name)}" title="${h(v.name)}" aria-pressed="${v.name===c.name}" style="--swatch-color:${D.colourSwatches[v.name]||'#aaa79e'}"><span aria-hidden="true"></span></button>`).join('')}${p.referenceColors.length>4?`<button class="product-more-colors" data-edit-quick="${p.id}" data-quick-color="${h(c.name)}" aria-label="${h(t('clMoreColors'))}">+${p.referenceColors.length-4}</button>`:''}</div>`}
