function homeEditCard(p){const c=p.referenceColors?.find(c=>c.name===editColourState[p.id])||p.referenceColors?.[0],color=c?.name||'',link=href('product/'+p.type+'.html',{ref:p.id,color});return `<article class="card home-edit-product" data-home-product="${p.id}"><div class="edit-product-media"><a href="${link}" class="card-photo"><img src="${referenceAsset(c.images[0])}" alt="${h(name(p)+' · '+color)}" loading="lazy">${c.images[1]?`<img class="card-photo-alt" src="${referenceAsset(c.images[1])}" alt="${h(name(p)+' · '+color)}" loading="lazy">`:''}</a></div><div class="edit-product-meta"><a href="${link}"><h3>${h(name(p))}</h3></a><p class="edit-product-code">Reference ${h(p.id)}</p>${productSwatches(p,c,'home')}${productAddControl(p,c)}</div></article>`}
function homeEditLookCard(look){const pairs=referenceLookPairs(look),index=Math.min(editLookColorState[look.id]||0,pairs.length-1),c=pairs[index];if(!c)return '';let colors=pairs.slice(0,4);if(!colors.includes(c))colors=[...colors.slice(0,3),c];return `<article class="card home-edit-product" data-home-look="${look.id}"><div class="edit-product-media"><button class="reference-look-photos" data-reference-look="${look.id}" data-look-index="${index}" aria-label="${h(t('shopLook'))}"><img src="${pairImage(c,'upper')}" alt="${h(t('Tanks & Tops'))}" loading="lazy"><img src="${pairImage(c,'bottom')}" alt="${h(t('Leggings'))}" loading="lazy"></button></div><div class="edit-product-meta"><h3>${h(t('stylingReference'))} ${h(look.id.slice(-3))}</h3><p class="edit-product-code">Reference ${h(look.id)}</p><div class="product-swatches" role="group" aria-label="${h(t('clColor'))}">${colors.map(v=>`<button class="product-swatch" data-home-look-swatch="${look.id}" data-look-index="${pairs.indexOf(v)}" data-color-name="${h(v.name)}" data-swatch-label="${h(v.name)}" aria-label="${h(v.name)}" title="${h(v.name)}" aria-pressed="${v===c}" style="--swatch-color:${D.colourSwatches[v.name]||'#aaa79e'}"><span aria-hidden="true"></span></button>`).join('')}${pairs.length>4?`<button class="product-more-colors" data-reference-look="${look.id}" data-look-index="${index}" aria-label="${h(t('clMoreColors'))}">+${pairs.length-4}</button>`:''}</div><button class="product-add-cta" data-reference-look="${look.id}" data-look-index="${index}">${editCartGlyph()}<span>${h(t('cardAdd'))}</span></button></div></article>`}
function openEditQuick(id,preferred=''){const p=products.find(p=>p.id===id);if(!p?.referenceDraft)return;const colors=p.referenceColors,active=colors.find(c=>c.name===preferred)||colors[0];openDialog(`<div class="edit-quick-dialog"><header><img id="editQuickPhoto" src="${referenceAsset(active.images[0])}" alt="${h(name(p))}"><div><h2>${h(name(p))}</h2><p>Style No. ${h(p.id)}</p></div></header><form id="editQuickForm"><label class="form-label">${h(t('colour'))}<select id="editQuickColor">${colors.map(c=>`<option ${c.name===active.name?'selected':''}>${h(c.name)}</option>`).join('')}</select></label><div class="edit-quick-fields"><label class="form-label">${h(t('size'))}<input id="editQuickSize" maxlength="40" placeholder="${h(t('ask'))}"></label><label class="form-label">${h(t('quantity'))}<input id="editQuickQty" type="number" min="1" max="999999" value="1" required></label></div><button class="btn" type="submit">${h(t('eqAdd'))}</button></form></div>`);$('editQuickColor').onchange=e=>{$('editQuickPhoto').src=referenceAsset(colors.find(c=>c.name===e.target.value).images[0])};$('editQuickForm').onsubmit=e=>{e.preventDefault();if(!$('editQuickForm').reportValidity())return;const item={id,qty:cartQty($('editQuickQty').value),colour:$('editQuickColor').value,size:$('editQuickSize').value.trim().slice(0,40)};if(addCartItems([item])){persist();updateCartUI();$('dialog').close();$('cartStatus').textContent=t('addedToCart');clearTimeout(cartToastTimer);cartToastTimer=setTimeout(()=>{if($('cartStatus'))$('cartStatus').textContent=''},2600)}}}
function setupEditDrag(){const track=$('editGrid');if(!track||track.dataset.dragReady)return;track.dataset.dragReady='true';track.tabIndex=0;track.setAttribute('role','region');track.setAttribute('aria-label',t('homeEditLabel'));let startX=0,startScroll=0,pointer=null,moved=false;track.addEventListener('dragstart',e=>e.preventDefault());track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,input,select'))return;pointer=e.pointerId;startX=e.clientX;startScroll=track.scrollLeft;moved=false});track.addEventListener('pointermove',e=>{if(pointer!==e.pointerId)return;const dx=e.clientX-startX;if(Math.abs(dx)>6){moved=true;track.setPointerCapture(pointer);track.classList.add('is-dragging')}if(moved){e.preventDefault();track.scrollLeft=startScroll-dx}});const end=e=>{if(pointer!==e.pointerId)return;if(track.hasPointerCapture(pointer))track.releasePointerCapture(pointer);pointer=null;track.classList.remove('is-dragging');setTimeout(()=>moved=false,0)};track.addEventListener('pointerup',end);track.addEventListener('pointercancel',end);track.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopImmediatePropagation()}},true);track.addEventListener('keydown',e=>{if(e.target!==track||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();track.scrollBy({left:(e.key==='ArrowLeft'?-1:1)*(track.firstElementChild?.offsetWidth||240),behavior:'instant'})})}
document.addEventListener('click',e=>{const ls=e.target.closest('[data-home-look-swatch]');if(ls){const id=ls.dataset.homeLookSwatch;editLookColorState[id]=Number(ls.dataset.lookIndex);ls.closest('[data-home-look]').outerHTML=homeEditLookCard(D.referenceLooks.find(l=>l.id===id));document.querySelector(`[data-home-look="${id}"] [data-color-name="${CSS.escape(ls.dataset.colorName)}"]`)?.focus();return}const sw=e.target.closest('[data-home-swatch]');if(sw){const id=sw.dataset.homeSwatch;editColourState[id]=sw.dataset.colorName;sw.closest('[data-home-product]').outerHTML=homeEditCard(products.find(p=>p.id===id));document.querySelector(`[data-home-product="${id}"] [data-color-name="${CSS.escape(sw.dataset.colorName)}"]`)?.focus();return}const b=e.target.closest('[data-edit-quick]');if(b)openEditQuick(b.dataset.editQuick,b.dataset.quickColor||'')});

