function fillHomeGrid(){const q=homeQuery.toLowerCase();const found=catalogueProducts().filter(p=>(homeType==='All'||p.type===homeType)&&(!q||(p.id+' '+p.name+' '+name(p)+' '+t(p.category)).toLowerCase().includes(q))).sort((a,b)=>Boolean(b.image)-Boolean(a.image));$('homeCount').textContent=found.length+' '+t('styles');$('homeGrid').innerHTML=found.length?found.slice(0,8).map(card).join(''):`<div class="empty">${h(t('noResults'))}</div>`;document.querySelectorAll('[data-home-type]').forEach(b=>b.classList.toggle('active',b.dataset.homeType===homeType))}

