const collectionFilters={shape:'',length:'',color:''},collectionColors={};let collectionLimit=12;
const collectionCategories=['All',...WOMEN_CATEGORIES];
const ct=k=>t('cl'+k);
function collectionShape(p){const n=p.name.toLowerCase();return n.includes('wide-leg')?'WideLeg':(n.includes('flared')||n.includes('flares'))?'Flared':n.includes('jogger')?'Joggers':p.category==='Pants & Leggings'?'Leggings':''}
function collectionColour(p){return p.referenceColors?.find(c=>c.name===collectionColors[p.id])||p.referenceColors?.find(c=>collectionFilters.color&&collectionColorMatches(c.name,collectionFilters.color))||p.referenceColors?.[0]}
function collectionBase(){return products.filter(p=>p.referenceDraft&&!p.legacy)}
function collectionFilterOptions(key,values){return `<details open><summary>${h(ct(key))}</summary><div class="cl-options"><label><input type="radio" name="cl-${key}" data-cl-filter="${key.toLowerCase()}" value="" ${!collectionFilters[key.toLowerCase()]?'checked':''}>${h(t('all'))}</label>${values.map(([v,label])=>`<label><input type="radio" name="cl-${key}" data-cl-filter="${key.toLowerCase()}" value="${h(v)}" ${collectionFilters[key.toLowerCase()]===v?'checked':''}>${h(label)}</label>`).join('')}</div></details>`}
const collectionColorFamilies={Beige:'#E6DFC7',Black:'#242522',Blue:'#2568A3',Brown:'#72543E',Green:'#697B58',Grey:'#92918E',Orange:'#DB916A',Pink:'#DCAFC0',Purple:'#806590',Red:'#AB4850',White:'#FFFDFA',Yellow:'#E5D575'};
function collectionColorFamily(name){const n=name.toLowerCase();if(/blackberry|aubergine|purple|plum|lilac|orchid|grape|lavender/.test(n))return 'Purple';if(/black|onyx/.test(n))return 'Black';if(/burgundy|cherry|red|wine|hibiscus|cranberry/.test(n))return 'Red';if(/pink|rose|blossom|fuchsia|mauve|berry|bubblegum|peony/.test(n))return 'Pink';if(/blue|navy|slate|glacier|ocean|cobalt|denim|teal|azure/.test(n))return 'Blue';if(/green|ivy|sage|olive|lime|mint|fern|forest|khaki/.test(n))return 'Green';if(/orange|copper|peach|coral|apricot/.test(n))return 'Orange';if(/yellow|lemon|butter|sunshine/.test(n))return 'Yellow';if(/ivory|white|pearl/.test(n))return 'White';if(/brown|espresso|chestnut|chocolate|mocha/.test(n))return 'Brown';if(/beige|cream|oat|sand|nude|biscuit/.test(n))return 'Beige';return 'Grey'}
function collectionColorMatches(name,value){return !value||(value.startsWith('family:')?collectionColorFamily(name)===value.slice(7):name===value)}
function collectionCategoryNav(){return `<nav class="cl-categories cl-text-categories" aria-label="${h(t('shopCategory'))}">${collectionCategories.map(c=>`<button data-category="${h(c)}" aria-pressed="${category===c}">${h(t(c==='All'?'clTitle':c))}</button>`).join('')}</nav>`}
function collectionColorChoices(colors){const families=[...new Set(collectionBase().flatMap(p=>p.referenceColors.map(c=>collectionColorFamily(c.name))))];return `<div class="cl-colour-choices cl-palette">${Object.entries(collectionColorFamilies).filter(([name])=>families.includes(name)).map(([name,hex])=>`<button type="button" data-cl-filter-color="family:${name}" aria-label="${h(t(name))}" aria-pressed="${collectionFilters.color==='family:'+name}" title="${h(t(name))}"><span style="background:${hex}" aria-hidden="true"></span><span class="cl-colour-tooltip">${h(t(name))}</span></button>`).join('')}</div>`}
function collectionSortChoices(){return `<details open class="cl-sort-filter"><summary>${h(t('sortLabel'))}</summary><div class="cl-sort-options">${[['featured','sortFeatured'],['name','sortName'],['reference','sortReference']].map(([value,label])=>`<label><input type="radio" name="cl-sort" data-cl-sort value="${value}" ${sortOrder===value?'checked':''}><span>${h(t(label))}</span></label>`).join('')}</div></details>`}
function syncCollectionControls(){document.querySelectorAll('[data-cl-filter-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.clFilterColor===collectionFilters.color)));document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)))}
function collectionPage(){const colors=[...new Set(collectionBase().flatMap(p=>p.referenceColors.map(c=>c.name)))].sort();return `<main class="collection-page catalogue-page wrap" data-grid="4"><header class="cl-intro"><span class="home-kicker">${h(t('womenLabel'))}</span><h1>${h(ct('Title'))}</h1><p>${h(ct('Intro'))}</p></header>${collectionCategoryNav()}<div class="cl-tools"><button id="clFilterToggle" class="cl-filter-toggle" aria-controls="clFilters" aria-expanded="true"><svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor"><path d="M3 6h18M3 12h18M3 18h18"/><circle cx="8" cy="6" r="2" fill="var(--cl-bg,#faf7f1)"/><circle cx="16" cy="12" r="2" fill="var(--cl-bg,#faf7f1)"/><circle cx="10" cy="18" r="2" fill="var(--cl-bg,#faf7f1)"/></svg><span id="clFilterLabel">${h(ct('HideFilters'))}</span></button><p id="resultsCount" role="status" aria-live="polite"></p><label class="sort-control">${h(t('sortLabel'))}<select id="sortOrder">${[['featured','sortFeatured'],['name','sortName'],['reference','sortReference']].map(([v,k])=>`<option value="${v}" ${sortOrder===v?'selected':''}>${h(t(k))}</option>`).join('')}</select></label><div class="cl-grid-controls" role="group" aria-label="${h(ct('Grid'))}">${[3,4].map(n=>`<button data-cl-density="${n}" aria-label="${n} ${h(ct('Grid'))}" aria-pressed="${n===4}"><svg viewBox="0 0 24 20" aria-hidden="true">${Array.from({length:n},(_,i)=>`<rect x="${2+i*(20/n)}" y="2" width="${20/n-2}" height="16" rx=".6"/>`).join('')}</svg></button>`).join('')}</div></div><div id="clActiveFilters" class="cl-active"></div><div class="cl-layout"><button id="clFilterShade" class="cl-shade" aria-label="${h(t('close'))}" hidden></button><aside id="clFilters" class="cl-sidebar" aria-label="${h(ct('Filters'))}"><div class="cl-sidebar-title"><strong>${h(ct('Filters'))}</strong><button id="clFilterClose" aria-label="${h(t('close'))}">×</button></div><label class="cl-search-label" for="search">${h(t('searchSubmit'))}</label><input id="search" class="cl-search" type="search" placeholder="${h(t('search'))}" value="${h(query)}">${collectionSortChoices()}<details open class="cl-type-filter"><summary>${h(ct('Type'))}</summary><div class="cl-type-options">${collectionCategories.map(c=>`<button data-category="${h(c)}" aria-pressed="${category===c}"><span aria-hidden="true"></span>${h(t(c==='All'?'all':c))}</button>`).join('')}</div></details>${collectionFilterOptions('Shape',[['Leggings',t('Leggings')],['Flared',ct('Flared')],['WideLeg',ct('WideLeg')],['Joggers',ct('Joggers')]])}${collectionFilterOptions('Length',['4.5','6.5'].filter(v=>collectionBase().some(p=>p.name.includes(v+'″'))).map(v=>[v,v+'″']))}<details open><summary>${h(ct('Color'))}</summary><select id="clColor" aria-label="${h(ct('Color'))}"><option value="">${h(t('all'))}</option>${Object.keys(collectionColorFamilies).map(n=>`<option value="family:${n}">${h(t(n))}</option>`).join('')}${colors.map(c=>`<option value="${h(c)}" ${collectionFilters.color===c?'selected':''}>${h(c)}</option>`).join('')}</select>${collectionColorChoices(colors)}</details><button id="clReset" class="cl-reset">${h(ct('Clear'))}</button><button id="clApply" class="btn cl-apply">${h(ct('ViewResults'))}</button></aside><div class="cl-results"><div class="grid cl-grid" id="catalogueGrid"></div><div class="cl-more" id="pagination"></div></div></div></main>`}
function collectionCard(p){const c=collectionColour(p),url=href('product/'+p.type+'.html',{ref:p.id,color:c.name}),src=referenceAsset(c.images[0]);return `<article class="card cl-card" data-cl-product="${p.id}"><a class="cl-product-link" href="${url}"><span class="card-photo"><img src="${src}" alt="${h(name(p)+' · '+c.name)}" loading="lazy">${c.images[1]?`<img class="card-photo-alt" src="${referenceAsset(c.images[1])}" alt="${h(name(p)+' · '+c.name+' · '+t('photos'))}" loading="lazy">`:''}</span><h3>${h(name(p))}</h3></a><p class="cl-card-reference">Reference ${h(p.id)}</p>${productSwatches(p,c,'collection')}${productAddControl(p,c)}</article>`}
function collectionFiltered(){const term=query.toLowerCase();let list=collectionBase().filter(p=>(category==='All'||category==='Sets'||p.category===category)&&(!collectionFilters.shape||collectionShape(p)===collectionFilters.shape)&&(!collectionFilters.length||p.name.includes(collectionFilters.length+'″'))&&(!collectionFilters.color||p.referenceColors.some(c=>collectionColorMatches(c.name,collectionFilters.color)))&&(!term||(p.id+' '+p.name+' '+name(p)+' '+p.referenceColors.map(c=>c.name).join(' ')).toLowerCase().includes(term)));list.sort((a,b)=>sortOrder==='name'?name(a).localeCompare(name(b),lang):sortOrder==='reference'?a.id.localeCompare(b.id):(collectionCategories.indexOf(a.category)-collectionCategories.indexOf(b.category)||a.id.localeCompare(b.id)));return list}
function fillCollection(){if(!$('catalogueGrid'))return;let list=collectionFiltered(),looks=[];if(category==='Sets'){const ids=new Set(list.map(p=>p.id));looks=(D.referenceLooks||[]).filter(l=>referenceLookPairs(l).some(c=>ids.has(c.bottom)&&(!collectionFilters.color||collectionColorMatches(c.name,collectionFilters.color)))&&(!query||(l.id+' '+l.colors.map(c=>c.name).join(' ')+' '+name(products.find(p=>p.id===l.bottomId))).toLowerCase().includes(query.toLowerCase())));if(sortOrder==='name')looks.sort((a,b)=>a.id.localeCompare(b.id));else if(sortOrder==='reference')looks.sort((a,b)=>a.id.localeCompare(b.id))}const total=category==='Sets'?looks.length:list.length,shown=Math.min(collectionLimit,total);$('resultsCount').textContent=total+' '+t(category==='Sets'?'stylingReference':'styles');$('catalogueGrid').innerHTML=total?(category==='Sets'?looks.slice(0,shown).map(l=>{const i=collectionFilters.color?referenceLookPairs(l).findIndex(c=>collectionColorMatches(c.name,collectionFilters.color)):0;return collectionLookCard(l,Math.max(0,i))}).join(''):list.slice(0,shown).map(collectionCard).join('')):`<div class="empty cl-empty"><p>${h(t('noResults'))}</p><button data-cl-reset class="btn light">${h(ct('Clear'))}</button></div>`;$('pagination').innerHTML=`<p>${shown} / ${total} ${h(ct('Shown'))}</p>${shown<total?`<button class="view-all-pill" data-cl-more>${h(ct('More'))}</button>`:''}`;document.querySelectorAll('.cl-categories [data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)));const labels={shape:ct(collectionFilters.shape),length:collectionFilters.length+'″',color:collectionFilters.color.startsWith('family:')?t(collectionFilters.color.slice(7)):collectionFilters.color};$('clActiveFilters').innerHTML=Object.entries(collectionFilters).filter(([,v])=>v).map(([k,v])=>`<button data-cl-clear="${k}">${h(labels[k])}<span aria-hidden="true">×</span></button>`).join('');if(category==='Sets')$('catalogueGrid').insertAdjacentHTML('afterbegin',`<p class="cl-pair-note">${h(t('referenceSetNote'))}</p>`);syncCollectionControls();syncCollectionUrl()}
function collectionLookCard(l,i){const c=referenceLookPairs(l)[i];return `<article class="card cl-look"><button class="reference-look-photos" data-reference-look="${l.id}" data-look-index="${i}" aria-label="${h(t('shopLook')+' · '+c.name)}"><img src="${pairImage(c,'upper')}" alt="${h(t('Tanks & Tops'))}" loading="lazy"><img src="${pairImage(c,'bottom')}" alt="${h(t(products.find(p=>p.id===c.bottom).category))}" loading="lazy"></button><h3>${h(t('stylingReference'))} ${h(l.id.slice(-3))}</h3><p>${h(c.name)}</p><button class="btn light" data-reference-look="${l.id}" data-look-index="${i}">${h(t('shopLook'))}</button></article>`}
function syncCollectionUrl(){try{const u=new URL(location.href);for(const [key,value] of Object.entries({category,search:query,shape:collectionFilters.shape,length:collectionFilters.length,color:collectionFilters.color,sort:sortOrder})){if(value&&value!=='All'&&value!=='featured')u.searchParams.set(key,value);else u.searchParams.delete(key)}history.replaceState(null,'',u)}catch{}}
function setCollectionFilters(open){const main=document.querySelector('.collection-page'),mobile=matchMedia('(max-width:800px)').matches;main.classList.toggle('cl-filters-open',open);main.classList.toggle('cl-filters-hidden',!open);$('clFilterToggle').setAttribute('aria-expanded',String(open));$('clFilterLabel').textContent=ct(open?'HideFilters':'ShowFilters');$('clFilterShade').hidden=!(mobile&&open);$('clFilters').inert=!open;if(mobile){document.body.classList.toggle('cl-lock',open);if(open)$('clFilterClose').focus();else $('clFilterToggle').focus()}}
function resetCollectionFilters(){Object.keys(collectionFilters).forEach(k=>collectionFilters[k]='');query='';collectionLimit=12;$('search').value='';$('clColor').value='';document.querySelectorAll('[data-cl-filter]').forEach(x=>x.checked=!x.value);fillCollection()}
function setupCollection(){const main=document.querySelector('.collection-page');if(!main)return;for(const k of Object.keys(collectionFilters))collectionFilters[k]=urlParams.get(k==='color'?'color':k)||collectionFilters[k];collectionLimit=12;sortOrder=['featured','name','reference'].includes(urlParams.get('sort'))?urlParams.get('sort'):sortOrder;$('sortOrder').value=sortOrder;$('clColor').value=collectionFilters.color;document.querySelectorAll('[data-cl-filter]').forEach(x=>x.checked=x.value===collectionFilters[x.dataset.clFilter]);fillCollection();$('sortOrder').onchange=e=>{sortOrder=e.target.value;document.querySelectorAll('[data-cl-sort]').forEach(x=>x.checked=x.value===sortOrder);collectionLimit=12;fillCollection()};document.querySelectorAll('[data-cl-sort]').forEach(x=>x.onchange=()=>{$('sortOrder').value=x.value;$('sortOrder').dispatchEvent(new Event('change'))});$('search').oninput=e=>{query=e.target.value;collectionLimit=12;fillCollection()};$('clColor').onchange=e=>{collectionFilters.color=e.target.value;Object.keys(collectionColors).forEach(k=>delete collectionColors[k]);collectionLimit=12;fillCollection()};document.querySelectorAll('[data-cl-filter]').forEach(x=>x.onchange=()=>{collectionFilters[x.dataset.clFilter]=x.value;collectionLimit=12;fillCollection()});$('clFilterToggle').onclick=()=>setCollectionFilters($('clFilterToggle').getAttribute('aria-expanded')!=='true');$('clFilterClose').onclick=$('clFilterShade').onclick=$('clApply').onclick=()=>setCollectionFilters(false);$('clReset').onclick=resetCollectionFilters;const mq=matchMedia('(max-width:800px)');mq.addEventListener('change',()=>{document.body.classList.remove('cl-lock');setCollectionFilters(!mq.matches)});setCollectionFilters(!mq.matches)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!document.querySelector('.collection-page'))return;if(b.hasAttribute('data-cl-more')){collectionLimit+=12;fillCollection()}if(b.hasAttribute('data-cl-color')){collectionColors[b.dataset.clColor]=b.dataset.colorName;const old=b.closest('article'),p=products.find(p=>p.id===b.dataset.clColor);old.outerHTML=collectionCard(p);document.querySelector(`[data-cl-product="${p.id}"] [data-color-name="${CSS.escape(b.dataset.colorName)}"]`)?.focus()}if(b.hasAttribute('data-cl-clear')){collectionFilters[b.dataset.clClear]='';collectionLimit=12;document.querySelectorAll('[data-cl-filter]').forEach(x=>x.checked=x.value===collectionFilters[x.dataset.clFilter]);$('clColor').value=collectionFilters.color;fillCollection()}if(b.hasAttribute('data-cl-reset'))resetCollectionFilters();if(b.hasAttribute('data-category'))collectionLimit=12});
document.addEventListener('keydown',e=>{if(!document.querySelector('.collection-page')||!matchMedia('(max-width:800px)').matches||$('clFilterToggle').getAttribute('aria-expanded')!=='true')return;if(e.key==='Escape'){e.preventDefault();setCollectionFilters(false)}if(e.key==='Tab'){const nodes=[...$('clFilters').querySelectorAll('button,input,select,summary')].filter(x=>x.getClientRects().length&&!x.disabled);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}});

