function fillCatalogue(){if(design==='b'){fillCollection();return}if(category==='Sets'){fillReferenceLooksCatalogue();return}let found=products.filter(p=>!p.legacy&&(!p.companion||!['All','Shorts','Leggings','Sets'].includes(category))).filter(p=>(category==='All'?WOMEN_CATEGORIES.includes(p.category):p.category===category)&&(!imageOnly||p.image)&&(p.id+' '+p.name+' '+name(p)+' '+t(p.category)).toLowerCase().includes(query.toLowerCase()));found.sort((a,b)=>sortOrder==='name'?name(a).localeCompare(name(b),lang):sortOrder==='reference'?a.id.localeCompare(b.id):Number(b.id==='991992364354')-Number(a.id==='991992364354'));let total=Math.max(1,Math.ceil(found.length/12));currentPage=Math.min(currentPage,total);$('resultsCount').textContent=found.length+' '+t('styles');$('catalogueGrid').innerHTML=found.length?found.slice((currentPage-1)*12,currentPage*12).map(card).join(''):`<div class="empty">${h(t('noResults'))}</div>`;$('pagination').innerHTML=Array.from({length:total},(_,i)=>`<button data-page="${i+1}" class="${i+1===currentPage?'active':''}">${i+1}</button>`).join('');document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category))}
