function readSharedCart(){const raw=new URLSearchParams(location.hash.slice(1)).get('cart');if(raw===null)return {present:false,valid:false,items:[]};try{if(raw.length>30000||!raw||!/^[A-Za-z0-9_-]+$/.test(raw))throw Error('Invalid link');const decoded=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(raw.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))));if(decoded.v!==1||!Array.isArray(decoded.items)||!decoded.items.length)throw Error('Invalid snapshot');const items=cleanCart(decoded.items.map(row=>{if(!Array.isArray(row)||row.length!==4)throw Error('Invalid line');return {id:row[0],qty:row[1],colour:row[2],size:row[3]}}),true);return {present:true,valid:true,items}}catch{return {present:true,valid:false,items:[]}}}
